package ocisync

import (
	"bytes"
	"context"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/x509"
	"encoding/binary"
	"encoding/pem"
	"fmt"
	"path"
	"regexp"
	"strings"
	"unicode/utf16"
)

// javaTruststorePaths are the truststores generated by the distribution tooling (ca-certificates-java,
// update-ca-trust); JDK packages of the distribution link their cacerts to them.
var javaTruststorePaths = []string{
	"/etc/ssl/certs/java/cacerts",              // Debian, Ubuntu, Alpine, Arch
	"/etc/pki/ca-trust/extracted/java/cacerts", // RHEL, CentOS, Fedora, UBI, Amazon Linux
	"/var/lib/ca-certificates/java-cacerts",    // openSUSE, SLES
}

const (
	// javaHomeTruststoreSuffix matches $JAVA_HOME/lib/security/cacerts (JDK 9+) and $JAVA_HOME/jre/lib/security/cacerts
	// (JDK 8) of every JDK/JRE in the image, e.g. /opt/java/openjdk, /usr/lib/jvm/*, /usr/local/openjdk-*, buildpacks.
	javaHomeTruststoreSuffix = "/lib/security/cacerts"
	// javaEnvTruststoreDir holds the separate truststore written for java: env.
	javaEnvTruststoreDir = "/etc/ssl/certs/java"
	// javaDefaultTruststorePassword is the well-known password of the JDK and distribution truststores.
	javaDefaultTruststorePassword = "changeit"

	jksMagic          = 0xFEEDFEED
	jksVersion        = 2
	jksTrustedCertTag = 2
)

var (
	javaTrustStoreOption         = regexp.MustCompile(`-Djavax\.net\.ssl\.trustStore=("[^"]*"|\S+)`)
	javaTrustStorePasswordOption = regexp.MustCompile(`-Djavax\.net\.ssl\.trustStorePassword=("[^"]*"|\S+)`)
	javaAliasUnsafeChars         = regexp.MustCompile(`[^a-z0-9._-]+`)
)

// applyJava writes a Java truststore with all certificates of bundle, the patched PEM bundle of the image. Images
// without a JDK/JRE (no truststore found) are left alone.
func (p *caCertificatesPatch) applyJava(ctx context.Context, fsys *imageFS, cfg *imageConfigFile, bundle []byte) error {
	if p.java == JavaTruststoreNone {
		return nil
	}

	toolOptions, _ := cfg.Env("JAVA_TOOL_OPTIONS")
	configuredStore := javaOptionValue(javaTrustStoreOption, toolOptions)
	password := javaOptionValue(javaTrustStorePasswordOption, toolOptions)
	if password == "" {
		password = javaDefaultTruststorePassword
	}

	// the image may configure its own truststore, that's the one the JVMs use
	configuredResolved := ""
	if configuredStore != "" && path.IsAbs(configuredStore) {
		resolved, node, err := fsys.resolve(configuredStore)
		if err != nil {
			return err
		}
		if node != nil && node.isRegular() {
			configuredResolved = resolved
		}
	}

	candidates := []string{}
	if configuredResolved != "" {
		candidates = append(candidates, configuredResolved)
	}
	for _, name := range fsys.find(func(name string) bool { return strings.HasSuffix("/"+name, javaHomeTruststoreSuffix) }) {
		candidates = append(candidates, "/"+name)
	}
	candidates = append(candidates, javaTruststorePaths...)

	type truststore struct {
		path string
		node *fsNode
	}
	var stores []truststore
	seen := map[string]bool{}
	for _, candidate := range candidates {
		resolved, node, err := fsys.resolve(candidate)
		if err != nil {
			return err
		}
		if node == nil || !node.isRegular() || seen[resolved] {
			continue
		}
		seen[resolved] = true
		stores = append(stores, truststore{path: resolved, node: node})
	}
	if len(stores) == 0 {
		return nil
	}

	data, err := encodeJavaTruststore(bundle, password)
	if err != nil {
		return fmt.Errorf("build java truststore: %w", err)
	}

	switch {
	case p.java == JavaTruststoreReplace:
		for _, store := range stores {
			fsys.WriteFile(store.path, data, store.node.mode, store.node.uid, store.node.gid)
		}
	case p.java == JavaTruststoreEnv && configuredStore != "":
		// JAVA_TOOL_OPTIONS already selects a truststore: replace that one instead of overriding the option. If it is
		// not part of the image (e.g. mounted at runtime), nothing is changed.
		if configuredResolved != "" {
			fsys.WriteFile(stores[0].path, data, stores[0].node.mode, stores[0].node.uid, stores[0].node.gid)
		}
	case p.java == JavaTruststoreEnv:
		storePath := path.Join(javaEnvTruststoreDir, "ocisync-"+p.safeName()+".jks")
		if err := writeFileIfChanged(ctx, fsys, storePath, data); err != nil {
			return err
		}
		options := fmt.Sprintf("-Djavax.net.ssl.trustStore=%s -Djavax.net.ssl.trustStoreType=JKS -Djavax.net.ssl.trustStorePassword=%s", storePath, password)
		if toolOptions != "" {
			options = toolOptions + " " + options
		}
		cfg.SetEnv("JAVA_TOOL_OPTIONS", options)
	}
	return nil
}

func javaOptionValue(option *regexp.Regexp, options string) string {
	match := option.FindStringSubmatch(options)
	if match == nil {
		return ""
	}
	return strings.Trim(match[1], `"`)
}

// encodeJavaTruststore encodes all certificates of a PEM bundle as JKS truststore. JKS is read by every JDK (8+); JDK
// 9+ also detects it where PKCS12 is expected (keystore.type.compat), e.g. for $JAVA_HOME/lib/security/cacerts.
// The output is deterministic for the same input.
func encodeJavaTruststore(bundle []byte, password string) ([]byte, error) {
	type entry struct {
		alias     string
		timestamp int64
		der       []byte
	}
	var entries []entry
	seen := map[[32]byte]bool{}
	for rest := bundle; ; {
		var block *pem.Block
		block, rest = pem.Decode(rest)
		if block == nil {
			break
		}
		// "TRUSTED CERTIFICATE" blocks (OpenSSL trust format) are skipped, the plain bundles contain the same certificates
		if block.Type != "CERTIFICATE" {
			continue
		}
		sum := sha256.Sum256(block.Bytes)
		if seen[sum] {
			continue
		}
		seen[sum] = true

		name, timestamp := "cert", int64(0)
		// some legacy roots can't be parsed by crypto/x509 (e.g. negative serials); they are kept with a generic alias
		if cert, err := x509.ParseCertificate(block.Bytes); err == nil {
			if cn := cert.Subject.CommonName; cn != "" {
				name = cn
			} else if len(cert.Subject.Organization) > 0 {
				name = cert.Subject.Organization[0]
			}
			timestamp = cert.NotBefore.UnixMilli()
		}
		slug := strings.Trim(javaAliasUnsafeChars.ReplaceAllString(strings.ToLower(name), "-"), "-")
		if len(slug) > 64 {
			slug = slug[:64]
		}
		entries = append(entries, entry{
			alias:     fmt.Sprintf("ocisync-%03d-%s", len(entries)+1, slug),
			timestamp: timestamp,
			der:       block.Bytes,
		})
	}
	if len(entries) == 0 {
		return nil, fmt.Errorf("CA bundle contains no certificates")
	}

	var buf bytes.Buffer
	write := func(v any) {
		_ = binary.Write(&buf, binary.BigEndian, v)
	}
	writeUTF := func(s string) {
		// aliases and the type are ASCII, where Java's modified UTF-8 equals UTF-8
		write(uint16(len(s)))
		buf.WriteString(s)
	}

	write(uint32(jksMagic))
	write(uint32(jksVersion))
	write(uint32(len(entries)))
	for _, e := range entries {
		write(uint32(jksTrustedCertTag))
		writeUTF(e.alias)
		write(e.timestamp)
		writeUTF("X.509")
		write(uint32(len(e.der)))
		buf.Write(e.der)
	}

	// integrity check: SHA-1 over the password (UTF-16BE), the string "Mighty Aphrodite" and the keystore content
	digest := sha1.New()
	for _, c := range utf16.Encode([]rune(password)) {
		digest.Write([]byte{byte(c >> 8), byte(c)})
	}
	digest.Write([]byte("Mighty Aphrodite"))
	digest.Write(buf.Bytes())
	buf.Write(digest.Sum(nil))

	return buf.Bytes(), nil
}
